import React, { useEffect, useState } from "react";
import axios from "axios";
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableContainer from '@mui/material/TableContainer';
import TableHead from '@mui/material/TableHead';
import TableRow from '@mui/material/TableRow';
import Paper from '@mui/material/Paper';

export default function Users() {
    const [users, setUsers] = useState([]); // State to store book data

    useEffect(() => {
        loadUsers(); // Load books when the component mounts
    }, []);

    const loadUsers = async () => {
        try {
            const result = await axios.get("http://localhost:8080/user");
            setUsers(result.data); // Set the fetched books to state
        } catch (error) {
            console.error("Error loading users:", error);
        }
    };

    return (
        <TableContainer component={Paper}>
            <Table sx={{ minWidth: 650 }} aria-label="books table">
                <TableHead>
                    <TableRow>
                        <TableCell>Title</TableCell>
                        <TableCell align="left">Author</TableCell>
                        <TableCell align="left">ISBN</TableCell>
                        <TableCell align="right">Quantity</TableCell>
                        <TableCell align="left">Added At</TableCell>
                    </TableRow>
                </TableHead>
                <TableBody>
                    {users.length > 0 ? (
                        users.map((user) => (
                            <TableRow key={user.id}>
                                <TableCell>{users.name}</TableCell>
                                <TableCell>{users.email}</TableCell>
                                <TableCell>{users.role}</TableCell>
                               </TableRow>
                        ))
                    ) : (
                        <TableRow>
                            <TableCell colSpan={5} align="center">
                                No books available
                            </TableCell>
                        </TableRow>
                    )}
                </TableBody>
            </Table>
        </TableContainer>
    );
}
